from taf.internal.scf.cm_data import CmData


class Raml:
    def __init__(self, tree):
        self._tree = tree
        self.cmData = CmData(self._tree.cmData)

    @property
    def xmlns(self):
        return self._tree.nsmap[None]

    @property
    def version(self):
        return self._tree.get("version")
